use uom::si::f64::{Length, Time};
use uom::si::length::{kilometer, meter};
use uom::si::time::second;

let span = Length::new::<kilometer>(3.0);
let gap  = Length::new::<meter>(500.0);
let total: Length = span + gap;                 // 3500 m, checked at compile time
let speed = total / Time::new::<second>(2.0);   // 1750 m/s
println!("{}", total.get::<meter>());
// Length::new::<kilometer>(1.0) + Time::new::<second>(1.0) does not compile

